def additional_video_effects(effect):
    items = [
        effect("video-outpaint", "Outpaint video", "Generate new canvas around the original clip with the official in/outpainting adapter.", "VFX", "video-outpaint", "", ["ltx-2.5"], video=True),
        effect("video-extend", "Extend video", "Continue motion after an explicitly selected source context. The generated continuation is additional footage.", "VFX", "video-extend", "Continue the scene naturally with coherent motion and lighting.", ["ltx-2.5"], video=True),
        effect("video-upscale", "AI video upscale", "Two-times pixel upscaling with the dedicated LTX 2.5 adapter; not a resize filter.", "Enhance", "video-upscale", "", ["ltx-2.5"], video=True),
        effect("alpha-matte", "Video alpha matte", "Extract the model's foreground alpha and combine it with the original RGB. Text cannot select an object.", "VFX", "alpha-matte", "", ["ltx-2.5"], video=True),
        effect("clean-plate", "Clean plate", "The dedicated adapter removes salient foreground content to reconstruct a clean background plate.", "VFX", "clean-plate", "The same environment without people or moving foreground subjects. Preserve the background architecture, objects, lighting, textures and camera motion.", ["ltx-2.5"], video=True),
        effect("sdr-to-hdr", "SDR to HDR", "Model-based HDR conversion with the official scene embedding and real high-bit-depth output.", "Enhance", "sdr-to-hdr", "", ["ltx-2.5"], video=True),
        effect("trim-video", "Trim video", "Trim the selected source interval without changing its frame rate or dimensions.", "Tools", "trim-video", "", ["video-tools"], video=True),
        effect("video-reframe", "Reframe video", "Explicitly crop or pad the source to the selected canvas and anchor.", "Tools", "video-reframe", "", ["video-tools"], video=True),
    ]
    items.append(effect("transition-video", "Video transition", "Generate a bridge between the actual start and end media using native endpoint guides.", "Video", "transition-video", "A coherent cinematic transition connecting the two supplied scenes.", ["ltx-2.5", "ltx-2.3-transition"]))
